begin;select plan(12);select has_column('public','apostolic_cities','population','population column exists');select has_column('public','apostolic_cities','satisfaction','satisfaction column exists');select has_table('public','apostolic_city_slot_catalog','city slot catalog exists');select is((select count(*)::integer from public.apostolic_city_slot_catalog),12,'twelve fixed city slots');select is((select count(*)::integer from public.apostolic_city_slot_catalog where terrain='coast'),2,'two coastal slots');select is((select count(*)::integer from public.apostolic_city_slot_catalog where unlock_town_hall_level=1),4,'level one opens three land slots and one coast slot');select results_eq($$select unlock_town_hall_level from public.apostolic_city_slot_catalog where slot_no between 5 and 11 order by slot_no$$,$$select expected from(values(3::smallint),(5::smallint),(8::smallint),(10::smallint),(14::smallint),(17::smallint),(24::smallint))as milestones(expected)$$,'land unlock milestones');select has_index('public','apostolic_city_buildings','apostolic_city_building_slot_idx','city building slot index exists');select function_returns('public','apostolic_sync_city_state',array[]::text[],'jsonb');select function_returns('public','apostolic_get_city_management',array[]::text[],'jsonb');select is((select count(*)::integer from pg_policies where schemaname='public'and tablename='apostolic_city_slot_catalog'),1,'slot catalog protected by RLS');select is((select count(*)::integer from information_schema.routine_privileges where routine_schema='public'and routine_name='apostolic_sync_city_state'and grantee='anon'),0,'anonymous role cannot synchronize cities');select*from finish();rollback;
